// === Tab: main ===
const CALM = true;

var p, t;

/*function preload(){
	img = loadImage("https://openprocessing.org/sketch/738158/files/hill1.jpg");
}*/

function setup() {
	createCanvas(1024, 768);
	p = [{pos: new p5.Vector(), vel: new p5.Vector()}];
	t = [new p5.Vector()];
	noStroke();
}

function draw() {
	background(0, 10);
	fill(60, 100, random(120, 255));
	for(let i in p){
		ellipse(p[i].pos.x, p[i].pos.y, 5, 5);
		t[i].x += cos(CALM ? noise(t[i].x/100, t[i].y/100) : noise(t[i].x/100, t[i].y/100, frameCount/100)*HALF_PI/2)*2;
		t[i].y += sin(CALM ? noise(t[i].x/100, t[i].y/100) : noise(t[i].x/100, t[i].y/100, frameCount/100)*HALF_PI/2)*2;
		if(p[i].x > width || p[i].y > height) {
			p = p.filter(x => x != p[i]);
			t = t.filter(x => x != t[i]);
		}
		let toT = new p5.Vector(t[i].x-p[i].pos.x, t[i].y-p[i].pos.y);
		toT.normalize();
		toT.mult(p[i].pos.dist(t[i])*4);
		let acc = p5.Vector.sub(toT, p[i].vel);
		acc.normalize();
		acc.mult(0.1);
		p[i].pos.add(p[i].vel);
		p[i].vel.add(acc);
	}
	if(frameCount % 1 == 0) {
		p.push({pos: p5.Vector.random2D().mult(2), vel: new p5.Vector()});
		t.push(new p5.Vector());
	}
}

